"Урок 27. Сигналы в космос": "27-дәрис. Космосқа сигналлар",
"Сигналы в космос": "Космосқа сигналлар",
"Объяснять, что такое оратория, и рассказывать, как люди с давних пор связывали музыку и звёздное небо.": "Ораторийә немә екәнлигини чүшәндүрүш вә адәмләрниң қедимдин буян музикини юлтузлуқ асман билән қандақ бағлиғанлиғини сөзләп бериш.",
"Вселенная": "Алам",
"Вселенная — это космос: звёзды, планеты и всё, что за пределами Земли. По-казахски это «ғалам», по-английски — «cosmos».": "Алам — бу космос: юлтузлар, планетилар вә Йәрниң сиртидики барлиқ нәрсә. Қазақчә бу «ғалам», инглизчә — «cosmos».",
"Звёзды и степь": "Юлтузлар вә дала",
"Наши предки смотрели на звёздное небо и наблюдали за небесными светилами. Звёзды помогали им ориентироваться в сторонах света и находить дорогу в степи.": "Ата-бовилиримиз юлтузлуқ асманға қарап, асман җисимлирини көзәткән. Юлтузлар уларға дунья тәрәплирини ениқлашқа вә далада йол тепишқа ярдәм бәргән.",
"Акыны и звёзды": "Ақинлар вә юлтузлар",
"Акыны хорошо знали основные планеты. Они воспевали их в своих песнях и складывали о них легенды.": "Ақинлар асасий планетиларни яхши билгән. Улар планетиларни нахшилирида мәдһийиләп, улар һәққидә риваятлар чиқарған.",
"Есепши": "Есепши",
"Есепши — это «счётчики»: люди, которые много лет вели наблюдения. Они давали прогнозы погоды и определяли время сезонных работ и перекочёвки на жайлау.": "Есепши — «һесаплиғучилар»: узун жиллар давамида көзитиш елип барған адәмләр. Улар һава райи мәлуматини бәргән вә мәвсүмлүк ишлар билән жайлаққа көчүш вақтини бекиткән.",
"Оратория и композитор": "Ораторийә вә композитор",
"Оратория — большое музыкальное произведение. Сыдык Мухамеджанов — казахский композитор (1924–1991), автор оратории «Голос веков», в которую он ввёл известную народную песню.": "Ораторийә — чоң музикилиқ әсәр. Сидиқ Мухамеджанов — қазақ композитори (1924–1991), «Әсирләр авази» ораторийәсиниң автори, униңға у мәшһур хәлқ нахшисини киргүзгән.",
"Два созвездия — разные названия": "Икки юлтуз түркүми — һәр хил намлар",
