"Верно. Полярная звезда играла важную роль в их жизни.": "Тоғра. Қутуп юлтузи уларниң һаятида муһим роль ойниған.",
"Неверно. «Жеті қарт» (семь старцев) — название Большой Медведицы.": "Хата. «Жеті қарт» (йәттә қери) — Чоң Айиқниң нами.",
