"Урок 28. Космическая музыка": "28-дәрис. Космослуқ музика",
"Космическая музыка": "Космослуқ музика",
"Объяснять, какую музыку называют космической, и называть инструменты и музыкантов, связанных с ней.": "Қандақ музикини космослуқ дәп атайдиғанлиғини чүшәндүрүш вә униң билән бағлиқ қураллар билән музикантларни атап бериш.",
"Космические звуки": "Космослуқ авазлар",
"С момента покорения космоса человек стал придумывать новые инструменты, которые издают «космические звуки». Так появился термин «космическая музыка».": "Инсан космосни бойсунғандин буян «космослуқ авазлар» чиқиридиған йеңи қуралларни ойлап тапқан. Шундақ қилип «космослуқ музика» термини пәйда болған.",
"По-казахски она называется «ғарыш музыкасы», по-английски — space music. Создать её можно с помощью электромузыкальных инструментов.": "Қазақчә у «ғарыш музыкасы», инглизчә — space music дәп атилиду. Уни электромузикилиқ қураллар арқилиқ яритишқа болиду.",
"Синтезатор": "Синтезатор",
"Синтезатор — самый распространённый электромузыкальный инструмент. С его помощью создают «космическую» музыку.": "Синтезатор — әң кәң тарқалған электромузикилиқ қурал. Униң билән «космослуқ» музика яритиду.",
"Жан-Мишель Жарр": "Жан-Мишел Жарр",
"Это французский композитор, который играет в основном на синтезаторах. Он одним из первых стал использовать синтезатор для «космических» композиций.": "Бу — асасән синтезаторларда чилидиған француз композитори. У «космослуқ» композицийәләр үчүн синтезаторни биринчиләрдин болуп қолланған.",
"Глюкофон": "Глюкофон",
"В 2005 году мир впервые услышал космическую музыку глюкофона. Доминиканский музыкант Фелле Вега показал первый прототип под названием «Tambiro».": "2005-жили дуня биринчи қетим глюкофонниң космослуқ музикисини аңлиди. Доминикилиқ музикант Фелле Вега «Tambiro» намлиқ биринчи прототипни көрсәткән.",
