"Урок 29. Космическая музыка": "29-дәрис. Космос музикиси",
"Рассказывать о проекте «Энергия звука» и называть людей, которые его создали.": "«Товуш энергияси» лайиһиси һәққидә сөзләш вә уни яратқан кишиләрни атап бериш.",
"Космос в музыке": "Музикидә космос",
"Композиторы разных стран использовали в своих произведениях тему космоса. Музыка помогает почувствовать красоту и величие космического пространства.": "Һәр хил әлләрниң композиторлири әсәрлиридә космос темисини ишләткән. Музика космос кеңлигиниң гөзәллики билән улуқлуқини һес қилишқа ярдәм бериду.",
"Энергия звука": "Товуш энергияси",
"Так называется грандиозная постановка в мире классической музыки. Шоу прошло в 2017 году в Астане и стало событием мирового уровня.": "Классик музика дунясидики грандиоз сәһнилишиниң нами шундақ. Шоу 2017-жили Астанида өткүзүлүп, дуня әһмийәтлик вақигә болди.",
"Идея проекта": "Лайиһиниң идеяси",
"Задумал шоу известный казахстанский скрипач и дирижёр Марат Бисенгалиев. Он был солистом и дирижёром проекта.": "Шоуни мәшһур қазақстанлиқ скрипкичи вә дирижёр Марат Бисенғалиев ойлап тапқан. У лайиһиниң солисти вә дирижёри болған.",
"Музыка и технологии": "Музика вә технологиялар",
"Создатели объединили классическую музыку в исполнении симфонического оркестра с передовыми технологиями. В шоу использовали новые 3D звуковые технологии.": "Яратқучилар симфониялик оркестр ижра қилған классик музикини илғар технологиялар билән бирләштүрди. Шоуда йеңи 3D товуш технологиялири ишлитилди.",
"Команда проекта": "Лайиһә командиси",
"Музыку написал британский композитор Карл Дженкинс. Режиссёр-постановщик — Василий Бархатов. Над шоу работала международная команда режиссёров, артистов, звукорежиссёров и продюсеров.": "Музикини британиялик композитор Карл Дженкинс язған. Сәһнә режиссёри — Василий Бархатов. Шоу устидә режиссёрлар, артислар, товуш режиссёрлири вә продюсерлардин тәркип тапқан хәлиқара команда ишлиди.",
"Кто есть кто в проекте": "Лайиһидә ким кимдур",
"Определи, о ком говорит карточка. Барсик подсказывает: вспомни, кто что делал в проекте «Энергия звука».": "Карточкида ким һәққидә сөз болуватқинини ениқла. Барсик әскәртиду: «Товуш энергияси» лайиһисидә кимниң немә қилғинини ядиңға кәлтүр.",
"О каком участнике проекта идёт речь?": "Лайиһиниң қайси иштирақчиси һәққидә сөз болуватиду?",
