"Верно. Он казахстанский скрипач и дирижёр.": "Тоғра. У қазақстанлиқ скрипкичи вә дирижёр.",
"Неверно. Он британский композитор и дирижёр.": "Хата. У британиялик композитор вә дирижёр.",
"Верно. Верно, он композитор проекта.": "Тоғра. Тоғра, у лайиһиниң композитори.",
"Верно. Верно, он режиссёр театра и кино.": "Тоғра. Тоғра, у театр вә кино режиссёри.",
"Верно. Использовали в том числе новые 3D звуковые технологии.": "Тоғра. Җүмлидин йеңи 3D товуш технологиялири ишлитилди.",
"Неверно. Звучала классическая музыка в исполнении симфонического оркестра.": "Хата. Симфониялик оркестр ижра қилған классик музика яңриди.",
"Верно. В неё входили режиссёры, артисты, звукорежиссёры и продюсеры.": "Тоғра. Униңға режиссёрлар, артислар, товуш режиссёрлири вә продюсерлар кирди.",
"Неверно. Они делают её на каждой репетиции.": "Хата. Улар буни һәр репетицияда қилиду.",
