"Урок 30. Вселенная звука": "30-дәрис. Товуш аләми",
"Вселенная звука": "Товуш аләми",
"Объяснять, почему музыку называют вселенной звука, и называть, как создаются новые музыкальные инструменты и произведения.": "Музикини немә үчүн товуш аләми дәп атайдиғанлиғини чүшәндүрүш вә йеңи музика әсваплири билән әсәрләрниң қандақ яритилидиғанлиғини атап бериш.",
"Музыку можно назвать вселенной. Это не огромное космическое пространство, а безграничное пространство, заполненное всевозможными звуками.": "Музикини аләм дәп атиса болиду. Бу чоң космос кеңлиги әмәс, бәлки һәр хил товушлар билән толған чекисиз кеңлик.",
"Какая Вселенная в космосе": "Космосдики аләм қандақ",
"Современная наука пока не знает, каковы реальные размеры Вселенной и есть ли у неё границы.": "Һазирқи пән аләмниң һәқиқий чоңлуғини вә униң чеграсиниң бар-йоқлуғини техи билмәйду.",
"Песня «Этот большой мир»": "«Бу чоң дуня» нахшиси",
"Её музыку написал В. Чернышев, а слова — Р. Рождественский. Песню слышно в кинофильме «Москва-Кассиопея».": "Униң музикисини В. Чернышев, сөзлирини Р. Рождественский язған. Нахша «Москва—Кассиопея» киносида аңлиниду.",
"Звуки Земли в космосе": "Йәр товушлири космоста",
"В песне космонавтам советуют взять в полёт звуки природы и обычной земной жизни. Так напоминание о доме летит вместе с ними.": "Нахшида космонавтларға сәпәргә тәбиәт вә ади йәр турмуши товушлирини елип кетиш тәвсийә қилиниду. Шундақ қилип, өй һәққидики әслитиш уларға һәмраһ болиду.",
"Вселенная звука расширяется": "Товуш аләми кеңийиватиду",
"Создаются новые произведения и инструменты, появляются переложения и аранжировки, восстанавливаются утерянные инструменты. Мы слушаем музыку и наслаждаемся музыкой природы.": "Йеңи әсәрләр вә әсваплар яритилиду, көчүрмиләр билән аранжировкилар пәйда болиду, йоқилип кәткән әсваплар әслигә кәлтүрүлиду. Биз музика аңлап, тәбиәт музикисидин ләззәтлинимиз.",
"Разложи по творческим группам": "Ижадий гурупларға бөл",
"Четыре творческие группы готовят проект «Вселенная звука». Определи, к какой группе относится каждая карточка.": "Төрт ижадий гуруп «Товуш аләми» лайиһисини тәйярлаватиду. Һәр карточкиниң қайси гурупқа мунасивәтлик екәнлигини ениқла.",
"К какой творческой группе относится?": "Қайси ижадий гурупқа мунасивәтлик?",
