"В пример приведён видеофрагмент о Венском овощном оркестре.": "Мисал сүпитидә Вена көкөт оркестри һәққидики видеопарчә берилгән.",
"Музыку можно назвать вселенной звуков.": "Музикини товушлар аләми дәп аташ мумкин.",
"Наука точно знает размеры Вселенной.": "Пән аләмниң чоңлуғини ениқ билиду.",
"Музыку песни «Этот большой мир» написал В. Чернышев.": "«Бу чоң дуня» нахшисиниң музикисини В. Чернышев язған.",
"Песню «Этот большой мир» написал М. Глинка.": "«Бу чоң дуня» нахшисини М. Глинка язған.",
"Авторы песни советуют взять в космос звуки природы и земной жизни.": "Нахшиниң авторлири космосқа тәбиәт вә йәр турмуши товушлирини елип чиқишни тәвсийә қилиду.",
"Вселенная звука не меняется и не расширяется.": "Товуш аләми өзгәрмәйду вә кеңәймәйду.",
"Переложения и аранжировки — это новые версии уже созданных произведений.": "Көчүрмиләр билән аранжировкилар — алдин яритилған әсәрләрниң йеңи варианти.",
"«Овощной оркестр» играет на сотовых телефонах.": "«Көкөт оркестри» мобил телефонларда чалиду.",
"«Кухонный оркестр» делает музыкальные игрушки из посуды или тары.": "«Ашхана оркестри» музика оюнчуқлирини идиш яки қапақ-қутилардин ясайду.",
"Вселенная звука — это то же самое, что космическое пространство со звёздами.": "Товуш аләми — юлтузлуқ космос кеңлиги билән бир нәрсә.",
"Это безграничное пространство, заполненное звуками.": "Бу товушлар билән толған чекисиз кеңлик.",
"Современная наука пока этого не знает.": "Һазирқи пән буни техи билмәйду.",
"Её музыка — В. Чернышева.": "Униң музикиси — В. Чернышевники.",
"Так космонавты возьмут с собой частичку Земли.": "Шундақ қилип, космонавтлар өзлири билән Йәрниң бир парчисини елип кетиду.",
"Она постоянно расширяется: появляются новые произведения и инструменты.": "У тохтимай кеңийиду: йеңи әсәрләр билән әсваплар пәйда болиду.",
"Они появляются на основе произведений, созданных ранее.": "Улар алдин яритилған әсәрләр асасида пәйда болиду.",
"Телефоны использует «SMART-оркестр», а овощной оркестр делает инструменты из овощей.": "Телефонларни «SMART-оркестр» ишлитиду, көкөт оркестри болса көкөтләрдин әсваплар ясайду.",
"Например, мелодии на пиалах и на коробках из-под сока.": "Мәсилән, пиалиларда вә шарбәт қутилирида чалған мелодияләр.",
"Вселенная звука — пространство всевозможных звуков, а не космос.": "Товуш аләми — һәр хил товушларниң кеңлиги, космос әмәс.",
"Верно. Это безграничное пространство, заполненное звуками.": "Тоғра. Бу товушлар билән толған чекисиз кеңлик.",
"Неверно. Современная наука пока этого не знает.": "Хата. Һазирқи пән буни техи билмәйду.",
"Верно. Слова написал Р. Рождественский.": "Тоғра. Сөзлирини Р. Рождественский язған.",
"Неверно. Её музыка — В. Чернышева.": "Хата. Униң музикиси — В. Чернышевники.",
"Верно. Так космонавты возьмут с собой частичку Земли.": "Тоғра. Шундақ қилип, космонавтлар өзлири билән Йәрниң бир парчисини елип кетиду.",
"Неверно. Она постоянно расширяется: появляются новые произведения и инструменты.": "Хата. У тохтимай кеңийиду: йеңи әсәрләр билән әсваплар пәйда болиду.",
"Верно. Они появляются на основе произведений, созданных ранее.": "Тоғра. Улар алдин яритилған әсәрләр асасида пәйда болиду.",
"Неверно. Телефоны использует «SMART-оркестр», а овощной оркестр делает инструменты из овощей.": "Хата. Телефонларни «SMART-оркестр» ишлитиду, көкөт оркестри болса көкөтләрдин әсваплар ясайду.",
"Верно. Например, мелодии на пиалах и на коробках из-под сока.": "Тоғра. Мәсилән, пиалиларда вә шарбәт қутилирида чалған мелодияләр.",
"Неверно. Вселенная звука — пространство всевозможных звуков, а не космос.": "Хата. Товуш аләми — һәр хил товушларниң кеңлиги, космос әмәс.",
