"Урок 31. Строим будущее вместе": "31-дәрис. Келәчәкни биллә қурамиз",
"Строим будущее вместе": "Келәчәкни биллә қурамиз",
"Объяснять, что такое компьютерная музыка, и рассказывать, как человек и компьютер вместе создают музыку.": "Компьютер музикисиниң немә екәнлигини чүшәндүрүш вә адәм билән компьютерниң музикини қандақ биллә яритидиғанлиғини сөзләп бериш.",
"Компьютерная музыка": "Компьютер музикиси",
"Компьютеры так прочно вошли в нашу жизнь, что в музыке появилось особое направление — компьютерная музыка. По-казахски: компьютерлік музыка, по-английски: computer music.": "Компьютерлар һаятимизға шунчилик чоңқур кирип кәлдики, музикида алаһидә йөнилиш — компьютер музикиси пәйда болди. Қазақчә: компьютерлік музыка, инглизчә: computer music.",
"Кто сочиняет музыку": "Музикини ким яритиду",
"Музыку сочиняет человек. Компьютер только помогает ему записать и обработать музыку.": "Музикини адәм яритиду. Компьютер пәқәт униңға музикини язишқа вә ишләшкә ярдәм бериду.",
"Аранжировка": "Аранжировка",
"Обработать музыку и дать ей новое звучание — значит аранжировать её. В этом тоже может помочь компьютер.": "Музикини ишләп, униңға йеңи авазлиқ бериш — уни аранжировка қилиш дегән мәна. Буниңдиму компьютер ярдәм берәләйду.",
"Программы для музыки": "Музика программилири",
"Есть много программ, в которых можно записывать собственную музыку: SunVox, NanoStudio, DarkWaveStudio и другие. Секреты записи музыкальных файлов ты узнаешь на уроках информатики.": "Өз музикаңни язалайдиған көп программилар бар: SunVox, NanoStudio, DarkWaveStudio вә башқилар. Музика файллирини язидиған сирларни информатика дәрислиридә үгинисән.",
"Старое и новое": "Кона вә йеңи",
"Мудрая пословица таджикского народа учит беречь прошлое, но знать и новое. Наша страна бережёт культурное наследие и осваивает новые технологии.": "Тәҗик хәлқиниң дана мақали өтмүшни асрашқа, лекин йеңилиқниму билишкә үгитиду. Бизниң әлимиз мәдәнийәт мирасини асрайду вә йеңи технологияләрни өзләштүриду.",
