"Объяснять, что такое музыка Победы, и подбирать к песне фото- и видеофрагменты, которые поддерживают её содержание.": "Ғәлибә музикисиниң немә екәнлигини чүшәндүрүш вә нахшиниң мәзмунини қоллайдиған фото вә видеопарчиләрни таллаш.",
"Праздничный май": "Байрамлиқ май",
"В каждом празднике есть свои особенности и традиции. Май особенный: в нём сразу несколько праздников, и у каждого есть песни-символы.": "Һәр байрамниң өз алаһидилиги вә әнәнилири бар. Май алаһидә: униңда бирақла бир нәччә байрам бар, һәр бириниң символ нахшилири бар.",
"Музыка Победы": "Ғәлибә музикиси",
"Так называют музыку, посвящённую Дню Победы. По-казахски она называется «Жеңіс музыкасы», по-английски — music of Victory.": "Ғәлибә күнигә беғишланған музикини шундақ атайду. Қазақчә у «Жеңіс музыкасы», инглизчә — music of Victory дәп атилиду.",
"Песня «День Победы»": "«Ғәлибә күни» нахшиси",
"Слова и музыку этой песни написала Л. Мельникова. В ней рассказывается о празднике мира, о памяти и о мирном Казахстане.": "Бу нахшиниң сөзлири билән музикисини Л. Мельникова язған. Униңда тинчлиқ байрими, әслимә вә тинч Қазақстан һәққидә сөзлиниду.",
"Два языка в песне": "Нахшидики икки тил",
"Припев этой песни звучит на русском и на казахском языках. Так песня объединяет людей, которые говорят на разных языках.": "Бу нахшиниң нақарати рус вә қазақ тиллирида яңрайду. Шундақ қилип нахша һәр хил тилларда сөзлишидиған кишиләрни бирләштүриду.",
"Видеоряд к музыке": "Музикиға видеоқатар",
"Фото- и видеофрагменты нужно подбирать так, чтобы они поддерживали содержание песни. Простой набор кадров о празднике — это ещё не видеоклип.": "Фото вә видеопарчиләрни нахшиниң мәзмунини қоллайдиған қилип таллаш керәк. Байрам һәққидики кадрларниң аддий топлими техи видеоклип әмәс.",
"Разложи по праздникам мая": "Майниң байрамлири бойичә бөл",
"Определи, к какому майскому празднику относится каждая карточка.": "Һәр карточкиниң майниң қайси байримиға мунасивәтлик екәнлигини ениқла.",
