"Объяснять, что такое авторская песня, и называть известных бардов и песни урока.": "Автор нахшиси немә екәнлигини чүшәндүрүш вә дәрисликтики мәшһур бардларни вә нахшиларни атап бериш.",
"Будущее": "Келәчәк",
"Будущее по-казахски «болашақ», по-английски «future». Во время прогулки или похода хорошо мечтать о том, каким оно будет.": "Келәчәк қазақчә «болашақ», инглизчә «future». Сәйлидә яки сәпәрдә униң қандақ болидиғини арман қилиш яхши.",
"Это песня Е. Крылатова из кинофильма «Гостья из будущего». Она заставляет подумать, что нужно делать сегодня, чтобы будущее было прекрасным для всех.": "Бу Е. Крылатовниң «Келәчәктин кәлгән меһман» киноғилмидики нахшиси. У келәчәкниң һәммә үчүн гөзәл болуши үчүн бүгүн немә қилиш керәклиги һәққидә ойландуриду.",
"Авторская песня": "Автор нахшиси",
"Авторскую песню ещё называют бардовской. Её особенность: слова, музыку, аккомпанемент и исполнение создаёт один и тот же человек.": "Автор нахшисини йәнә бард нахшиси дәп атайду. Униң алаһидилиги: сөзи, музикиси, аккомпаниментини вә ижрасини бир адәмниң өзи яратиду.",
"Известные барды": "Мәшһур бардлар",
"Авторские песни писали и исполняли Булат Окуджава, Юрий Визбор, Владимир Высоцкий, Ада Якушева, Татьяна и Сергей Никитины, Виктор Берковский, Дмитрий Сухарев.": "Автор нахшилирини Булат Окуджава, Юрий Визбор, Владимир Высоцкий, Ада Якушева, Татьяна билән Сергей Никитинлар, Виктор Берковский, Дмитрий Сухарев йезип ейтқан.",
"Почему такие песни популярны": "Мундақ нахшилар немишқа мәшһур",
"В них часто звучит тема любви к родному краю. Мелодии простые, легко запоминаются, и подпеть исполнителю может каждый. Ещё в уроке есть песня В. Шаинского «Вместе весело шагать» на слова М. Матусовского.": "Уларда көпинчә туғулған йәргә болған муһәббәт темиси яңрайду. Мелодиялири оддий, асан есидә қалиду, ижрачиға һәммә қошулуп ейталайду. Дәристә йәнә В. Шаинскийниң М. Матусовскийниң сөзигә язған «Бирликтә маңғили хошал» нахшиси бар.",
"Разложи по ролям": "Роллар бойичә айри",
"Определи, кто перед тобой: бард или композитор и поэт, которые упомянуты в уроке.": "Алдиңда кимниң турғинини ениқла: дәристә тилға елинған бард яки композитор вә шаир.",
