"Это музыкальный жанр.": "Бу музика жанри.",
"Музыкальный ЗУХ": "Музикилиқ БУК",
"Реши, в какой столбик таблицы «Музыкальный ЗУХ» нужно записать каждую запись.": "«Музикилиқ БУК» җәдвилиниң қайси бағиниға һәр бир йезиқни йезиш керәклигини бәлгиләп чиқ.",
"В какой столбик это записать?": "Буни қайси бағиниға йезиш керәк?",
