"Удивился": "Һәйран қалдим",
"Хочу узнать": "Билгүм бар",
"Термин, который мне очень понравился": "Маңа жуда ойған термин",
"Это то, что ты уже знаешь.": "Бу сән алдинала билидиған нәрсә.",
"Имя музыканта, которое я запомнил": "Мән әсимдә сақлиған музикантниң исми",
"Название произведения, которое меня заинтересовало": "Мени қизиқтурған әсәрниң намы",
