"То, что удивило меня на уроках музыки": "Музика дәрислиридә мени һәйран қалдурған нәрсә",
"Тут слова-маячки об удивлении.": "Бу йәрдә һәйран қелиш һәққидики йол көрсәткүч сөзләр.",
"То, что удивило меня летом": "Язда мени һәйран қалдурған нәрсә",
"То, чем я хочу поделиться с классом": "Синипқа ейтип бәргүм кәлгән нәрсә",
"Это связано с тем, что тебя удивило.": "Бу сени һәйран қалдурған нәрсигә бағлиқ.",
"Вопрос, который появился у меня летом": "Язда мәндә пәйда болған соал",
"Этот столбик можно заполнять всё лето.": "Бу бағинини пүтүн яз давамида толтуруш мумкин.",
"То, о чём я хочу спросить учителя": "Мәллимдин сориғум келидиған нәрсә",
"Ты пока этого не знаешь.": "Сән буни һазирчә билмәйсән.",
"То, что я хочу узнать в новом учебном году": "Йеңи оқуш йилида билгүм келидиған нәрсә",
"Этот столбик про будущие открытия.": "Бу баған келәчәктики кәшпийатлар һәққидә.",
"Как называется таблица, которую предлагается вести на каникулах?": "Каникулда жүргүзүш тәклип қилинидиған җәдвәл қандақ атилиду?",
"Музыкальный дневник": "Музика күндилик дәптири",
"Нотная тетрадь": "Нота дәптири",
"Таблица умножения": "Көпәйтиш җәдвили",
"Таблица называется «Музыкальный ЗУХ».": "Җәдвәл «Музикилиқ БУК» дәп атилиду.",
"Сколько столбиков в таблице «Музыкальный ЗУХ»?": "«Музикилиқ БУК» җәдвилидә нәччә баған бар?",
"Три": "Үч",
"Два": "Икки",
