"Столбики: «Знаю», «Удивился», «Хочу узнать».": "Бағанлар: «Билимән», «Һәйран қалдим», «Билгүм бар».",
"Что записывают в столбик «Знаю»?": "«Билимән» бағиниға немә йезилиду?",
"Понятия, термины, имена музыкантов, названия произведений, которые понравились": "Ойған чүшәнчиләр, терминлар, музикантларниң исимлири, әсәрләрниң намлири",
"Только оценки за четверть": "Пәқәт чарәк баһалири",
"Список книг на лето": "Яз үчүн китаплар тизимлиги",
"Адреса друзей": "Дослириниң адресләри",
"В «Знаю» вносят то, что тебя заинтересовало и что ты запомнил.": "«Билимән» бағиниға сени қизиқтурған вә әсиңдә қалған нәрсиләр киргүзүлиду.",
"Какой столбик можно заполнять всё лето?": "Қайси бағинини пүтүн яз давамида толтуруш мумкин?",
"Ни один": "Һечқайсиси",
