"Байқоңыр": "Байқоңур",
"Байқоңыр туралы музыкалық шығарманы тыңдап, оның авторларын, орындаушыларын және музыкалық формасын атау.": "Байқоңур һәққидики музикилиқ әсәрни аңлап, униң авторлирини, ада қилғучилирини вә музикилиқ шәклини аташ.",
"Байқоңыр қандай жер?": "Байқоңур қандақ йәр?",
"Байқоңыр — ғарышқа зымыран ұшырылатын жер. Ғалымдар оны ғарышқа ұшуға ең қолайлы жер деп таңдаған.": "Байқоңур — космосқа ракета учурулидиған йәр. Алимлар уни космосқа учушқа әң қулайлиқ йәр дәп таллиған.",
"Неге дәл Байқоңыр?": "Немишқа айни Байқоңур?",
"Байқоңыр экваторға жақын, сондықтан мұнда Жердің тартылыс күші аз. Зымыранға ғарышқа көтерілу жеңілірек.": "Байқоңур экваторға йеқин, шуңа бу йәрдә Жерниң тартиш күчи аз. Ракетиға космосқа көтүрүлүш йеник болиду.",
"Экватор дегеніміз не?": "Экватор дегән немә?",
"«Экватор» латын тілінде «теңестіргіш» деген мағына береді. Жер шарының дәл ортасынан өтетін шартты сызық экватор сызығы деп аталады.": "«Экватор» латин тилида «тәңләштүргүч» дегән мәнани бериду. Жер шариниң дәл оттурисидин өтидиған шәртлик сизиқ экватор сизиғи дәп атилиду.",
"«Байқоңыр» шығармасы": "«Байқоңур» әсири",
"Бұл — композитор А. Алмағанбетовтың музыкалық шығармасы. Оны халық аспаптар ансамблі орындайды.": "Бу — композитор А. Алмағанбетовниң музикилиқ әсири. Уни хәлиқ чалғулири ансамбли ада қилиду.",
"Кімге арналған?": "Кимгә беғишланған?",
"Композитор шығарманы тұңғыш қазақ ғарышкері Т. Әубәкіровке арнаған. Сонымен қатар «Байқоңыр» атты ән бар: сөзін А. Рахметов, әнін А. Алмағанбетов жазған.": "Композитор әсәрни тунҗи қазақ космонавти Т. Аубакировқа беғишлиған. Шундақла «Байқоңур» дегән нахша бар: сөзини А. Рахметов, нахшисини А. Алмағанбетов язған.",
"Байқоңыр туралы ұғымдарды топтастыр": "Байқоңур һәққидики чүшәнчиләрни топла",
