"28-сабақ. Ғарыш әуені": "28-дәрис. Космос авази",
"Ғарыш әуені": "Космос авази",
"Ғарыш ұғымын түсіндіру, халықтық, классикалық және эстрадалық музыканы ажырату, синтезатор, фортепиано және орган аспаптарын ажырата білу.": "Космос чүшәнчисини чүшәндүрүш, хәлиқ, классикилиқ вә эстрада музикисини пәриқләндүрүш, синтезатор, фортепиано вә орган чалғулирини пәриқләндүрүшни билиш.",
"Ғарыш дегеніміз не?": "Космос дегән немә?",
"Ғарыш – Жерді қоршаған шексіз кеңістік. Күн, Ай, Жер, жұлдыздар және басқа галамшарлар ғарыш әлемін құрайды.": "Космос — Жерни қоршиған чәксиз кеңлик. Қуяш, Ай, Жер, юлтузлар вә башқа планетилар космос дунясини тәшкил қилиду.",
"Дидье Маруани": "Дидье Маруани",
"Дидье Маруани – француз композиторы. Оны «синтезаторлар патшасы» деп атаған. Ол «Симфония» шығармасының музыкасын жазған.": "Дидье Маруани — француз композитори. Уни «синтезаторлар падишаһи» дәп атиған. У «Симфония» әсириниң музикисини язған.",
"«Спейс» рок тобы": "«Спейс» рок групписи",
"Дидье Маруани құрған «Спейс» рок тобы 1980 жылдары бүкіл әлемге танымал болды. «Симфония» шығармасын осы топ орындаған.": "Дидье Маруани қурған «Спейс» рок групписи 1980-жиллири пүткүл дунягә мәшһур болди. «Симфония» әсирини мошу группа ада қилған.",
"Музыка бағыттары": "Музика йөнилишлири",
"Халықтық музыка – ұлттық ән-күй, жырлар. Классикалық музыка – симфония, опера, сюита, романс. Эстрадалық музыка – электронды аспаптармен өңделген шығармалар.": "Хәлиқ музикиси — милли нахша-күйләр, жирлар. Классикилиқ музика — симфония, опера, сюита, романс. Эстрада музикиси — электронлуқ чалғулар билән ишләнгән әсәрләр.",
"Поп, рок және стиль": "Поп, рок вә стиль",
"Поп музыка – көпшілікке арналған, танымал, тыңдауға жеңіл музыка. Рок музыка – электронды аспаптармен орындалатын, нақты (ауыр) ырғақты музыка. Стиль – композитор немесе орындаушының музыкалық бейнені берудегі бағыты.": "Поп музика — көпчиликкә беғишланған, мәшһур, аңлашқа йеник музика. Рок музика — электронлуқ чалғулар билән ада қилинидиған, ениқ (еғир) ритмлиқ музика. Стиль — композитор яки ада қилғучиниң музикилиқ образни бериштики йөнилиши.",
