"29-сабақ. Мен ғарышкер боламын": "29-дәрис. Мән космонавт боламән",
"Мен ғарышкер боламын": "Мән космонавт боламән",
"Ғарыш тақырыбындағы шығармаларды атау және оркестрлік пьеса мен әнді бір-бірінен ажырату.": "Космос темисидики әсәрләрни атап, оркестрлиқ пьеса билән нахшини бир-биридин пәриқләндүрүш.",
"Адамның Айға ұшуы": "Адәмниң Айға учуши",
"20-ғасырдағы үлкен жаңалықтардың бірі — адамның Айға ұшуы. Бұл оқиға әлем музыканттарына да қатты әсер етті.": "20-әсирдики чоң йеңилиқларниң бири — адәмниң Айға учуши. Бу вакә дунядики музыкантларғиму қаттиқ тәсир қилди.",
"Ғарыш тақырыбы": "Космос темиси",
"Музыканттар ғарыш тақырыбына түрлі жанрда шығармалар жазды. Олардың бірі — америкалық композитор Ч. Айвздың оркестрлік пьесасы.": "Музыкантлар космос темисида һәр хил жанрда әсәрләр йезишти. Уларниң бири — америкалиқ композитор Ч. Айвзниң оркестрлиқ пьесиси.",
"«Ғарыш пейзажы»": "«Космос пейзажи»",
"Бұл пьесаны симфониялық оркестр орындайды. Кейін шығарманың аты өзгеріп, «Жауапсыз қалған сұрақ» болды.": "Бу пьесини симфониялик оркестр орунлайду. Кейин әсәрниң нами өзгирип, «Жавапсиз қалған соал» болди.",
"Музыка арқылы әңгіме": "Музика арқилиқ һекайә",
"Музыкада төрт ғарышкер белгісіз ғаламшарға ұшады. Ондағы тұрғындар дыбыс арқылы 7 рет сұрақ қояды, бірақ жауап ала алмайды.": "Музикида төт космонавт намәлум планетаға учиду. У йәрдики аһали аваз арқилиқ 7 қетим соал қойиду, амма жавап алалмайду.",
"«Мен ғарышкер боламын»": "«Мән космонавт боламән»",
"Бұл — ғарышкер болуды армандайтын баланың әні. Өлеңін С. Қамшыгер, әнін Ө. Алтаев жазған. Әнде шумақтар мен қайырма бар.": "Бу — космонавт болушни арман қилидиған баланиң нахшиси. Шеирини С. Қамшыгер, нахшисини Ө. Алтаев йезип чиққан. Нахшида куплетлар вә нақарат бар.",
