"Жылдар және ғарыш музыкасы": "Жиллар вә космос музикиси",
"Ғарыш тақырыбындағы шығармаларды, олардың композиторларын атау және соната ұғымын түсіндіру.": "Космос темисидики әсәрләрни, уларниң композиторлирини аташ вә соната уқумини чүшәндүрүш.",
"Ғарыш және музыка": "Космос вә музика",
"Адамдар ғарышты сұлулық пен үйлесімділіктің, бірлік пен ынтымақтың мекені деп санаған. Ғарышқа жол ашылмай тұрған ғасырларда да ұлы композиторлар ғарыш әсемдігін музыка арқылы берген.": "Адәмләр космосни гөзәллик билән уйғунлуқниң, бирлик билән иттипақлиқниң макани дәп һесаплиған. Космосқа йол ечилмиған әсирләрдиму улуқ композиторлар космос гөзәллигини музика арқилиқ ипадилигән.",
"Ұлы композиторлар": "Улуқ композиторлар",
"А. Вивальди — итальяндық, Л. Бетховен — неміс композиторы. Олармен бірге В.А. Моцарт та ғарыш тақырыбын музыкасында көрсеткен. Вивальди есімімен Меркурий ғаламшарындағы бір кратер аталады.": "А. Вивальди — италийәлик, Л. Бетховен — немис композитори. Улар билән биллә В.А. Моцартму космос темисини музикисида көрсәткән. Вивальдиниң еси билән Меркурий планетасидики бир кратер атилиду.",
"Ғарыштық атаулар": "Космос намлири",
"Композиторлар өз шығармаларына ғаламшар мен ай аттарын қойған. Мысалы, Моцарттың «Юпитер» симфониясы және Бетховеннің «Ай нұры» сонатасы.": "Композиторлар өз әсәрлиригә планета вә ай намлирини қойған. Мәсилән, Моцартниң «Юпитер» симфонияси вә Бетховенниң «Ай нури» сонатиси.",
"Соната дегеніміз не?": "Соната дегән немә?",
"Соната — бірнеше қарама-қарсы бөліктен тұратын аспаптық шығарма. «Ай нұры» сонатасы фортепиано аспабына арналған. Оны зейін қойып, тыныш тыңдайды.": "Соната — бирнәччә бир-биригә қарима-қарши қисимдин тәркиб тапқан чилғу әсири. «Ай нури» сонатиси фортепиано қураливиға атап йезилған. Уни диққәт билән, тинч аңлайду.",
"Қазіргі заман музыкасы": "Һазирқи заман музикиси",
"Ғарыш тақырыбы бүгінгі музыкада да бар: француз композиторы Д. Маруани «Спейс» рок тобын басқарған, ал Ч. Айвз ғарыштық музыкасымен белгілі. Француз композиторы Жан Мишель Жарр заманауи музыканың дамуына үлес қосқан.": "Космос темиси бүгүнки музикидиму бар: франсузийәлик композитор Д. Маруани «Спейс» рок топиға башчилиқ қилған, Ч. Айвз болса космос музикиси билән мәшһур. Франсузийәлик композитор Жан Мишель Жарр заманивий музикиниң риваҗлинишиға төһпә қошқан.",
"Бұрынғы шебер ме, бүгінгі музыка ма?": "Илгирики уста музика яки бүгүнки музика?",
