"Әрбір өнер адамы өз туындылары болашақта орындалса деп армандайды. Ескі әндер мен жырлар бізге жетіп, әлі де орындалып келеді.": "Һәр бир сәнәт егиси өз әсәрлириниң келәчәктә орунлинишини арман қилиду. Көһнә нахшилар вә жирлар бизгә йетип кәлди, һелиму орунлинип келиватиду.",
