"Электронды музыкалық аспаптар мен сахналық шоуды танып, «Мен қазақпын» және «Асыл арман» әндері туралы айта білу": "Электронлуқ музикилиқ қураллар вә сәһнә шоусини тонуп, «Мен қазақмән» вә «Асыл арман» нахшилири һәққидә сөзләп берәләш",
"Life for Water шоуы": "Life for Water шоуси",
"Бұл — Жан Мишель Жарр қатысқан концерттік шоу. Ол 2006 жылы Марокконың Сахара шөлінде өтті.": "Бу — Жан Мишель Жарр қатнашқан концерт шоуси. У 2006-жили Мароккониң Саһара чөлидә өткүзүлгән.",
"Ол — француз электронды музыканты. Өз шоуларында қызықты заманауи құралдарды қолданады.": "У — французийәлик электронлуқ музыкант. Өз шоуларида қизиқарлиқ заманивий қуралларни ишлитиду.",
"Лазерлік арфа өзі дыбыс шығармайды. Ол ноталарды басқа синтезаторларға бағыттайды.": "Лазерлиқ арфа өзи аваз чиқармайду. У ноталарни башқа синтезаторларға йөнәлдүриду.",
"Шоу және рэп": "Шоу вә рэп",
"Шоу — көңіл көтеретін бағдарламаға құрылған қойылым, іс-шара. Рэп — речитативтік (өлеңдетіп оқу) ырғақтық музыка.": "Шоу — көңүл ечиш программисиға қурулған қоюлум, тәдбир. Рэп — речитатив (шеирни ейтқандәк оқуш) уссуллуқ музика.",
"Реактейбл": "Реактейбл",
"Реактейбл — испан өнер тапқыштары ойлап тапқан электронды аспап. Ол сенсорлық беткейі бар дөңгелек үстел тәрізді, оны бір немесе бірнеше адам қатар ойнай алады.": "Реактейбл — испаниялик ихтирачилар ойлап тапқан электронлуқ қурал. У сенсорлуқ йүзи бар төгилик столға охшайду, уни бир яки бир нәччә адәм биллә чалалайду.",
