"Қазақстан болашағы және музыка": "Қазақстанниң келәчиги вә музика",
"Түсіндіру: дәстүрлі музыкалық өнер мен заманауи музыка болашақта қатар жүреді, ал болашаққа деген сенім өз құндылықтарымызды құрметтеумен байланысты.": "Чүшәндүрүш: аниәнивий музикилиқ санәт билән заманивий музика келәчәктә йенму-йән маңиду, келәчәккә болған ишәнч болса өз қиммәтлиримизни һөрмәтләш билән бағлиқ.",
"Бұл әннің композиторы — С. Еркімбеков. Әнде балалар қандай болашақ туралы армандайтыны айтылады.": "Бу нахшиниң композитори — С. Еркимбеков. Нахшида балиларниң қандақ келәчәк һәққидә арман қилидиғанлиқи ейтилиду.",
"Болашаққа сенім": "Келәчәккә ишәнч",
"Қазақстан бүгінгі күні нық сеніммен болашаққа алға басты. Мұндай сенімділік халықтың өз құндылықтарын құрметтеп, сақтап қалуымен тығыз байланысты.": "Қазақстан бүгүнки күндә мустәһкәм ишәнч билән келәчәккә алға маңди. Мундақ ишәнч хәлқниң өз қиммәтлирини һөрмәтләп, сақлишиға зич бағлиқ.",
"Халықтың құндылықтары": "Хәлқниң қиммәтлири",
"Халықтың құндылықтарына оның тілі, дәстүрі, мәдениеті және өнері жатады. Оларды құрметтеп, сақтау — болашақтың негізі.": "Хәлқниң қиммәтлиригә униң тили, аниәнилири, мәдәнийити вә санәти кириду. Уларни һөрмәтләп сақлаш — келәчәкниң асасидур.",
"Дәстүр мен жаңашылдық": "Аниәнә вә йеңилиқ",
"Дәстүрлі музыкалық өнер мен заманауи музыка өзара үйлесімділікте болашақта қатар жүреді. Олар бір-бірін жоққа шығармайды.": "Аниәнивий музикилиқ санәт билән заманивий музика өз ара мувапиқлиқта келәчәктә йенму-йән маңиду. Улар бир-бирини инкар қилмайду.",
"Әнді қалай орындайды": "Нахшини қандақ орунлайду",
"«Асыл арман» әнінде жеке дауыс, хор және тақпақ түрінде айтылатын тұстар бар. Әнді халық аспаптары немесе оркестр сүйемелдеуі мүмкін.": "«Асыл арман» нахшисида алаһидә аваз, хор вә ритмлиқ оқуш шәклидә ейтилидиған җайлар бар. Нахшиға хәлқ қураллири яки оркестр һәмраһ болуши мумкин.",
"Музыкалық стильдер, аспаптар және оркестрлер": "Музикилиқ стиллар, қураллар вә оркестрлар",
"Әр карточканы өз тобына қой. Барсик көмектеседі!": "Һәр бир карточкини өз топиға қой. Барсик ярдәм бериду!",
